<?php get_header();$id=get_the_ID();$url=get_post_meta($id,'gc_event_registration_url',true); ?>
<main class="gc-interior"><section class="gc-page-hero gc-dark"><div class="gc-container"><span class="gc-kicker">Game Changers event</span><h1><?php the_title();?></h1><p><?php echo esc_html(get_post_meta($id,'gc_event_type',true)?:'Community event');?></p></div></section><section class="gc-section"><div class="gc-container gc-detail-grid"><article class="gc-prose"><?php the_content();?></article><aside class="gc-detail-aside"><h3>When</h3><strong><?php echo esc_html(get_post_meta($id,'gc_event_date',true));?></strong><span><?php echo esc_html(get_post_meta($id,'gc_event_start_time',true));?><?php if(get_post_meta($id,'gc_event_end_time',true))echo ' – '.esc_html(get_post_meta($id,'gc_event_end_time',true));?></span><h3>Where</h3><p><?php echo esc_html(get_post_meta($id,'gc_event_location',true));?></p><?php if($url):?><a class="gc-button gc-button-green" href="<?php echo esc_url($url);?>" target="_blank" rel="noopener">Register</a><?php endif;?></aside></div></section></main><?php get_footer();?>
